D['adi']=dict(desc='Ādi Lakṣmī, the first of the Aṣṭa Lakṣmī: the primordial Lakṣmī, Bhṛgu’s daughter and Viṣṇu’s eternal consort; her form with lotus and flag, Śrī in Pāñcarātra and Śrīvaiṣṇava thought, puruṣakāra, Śrī on Viṣṇu’s chest, and Padmāvatī of Tirumala.',
 tag='The first, the source of all fortune',fwq=("Why is she 'first'?","She is Lakṣmī before any gift: the Goddess herself, always with Viṣṇu."),
 fw=['<b>Ādi Lakṣmī</b> means “the first” or “primordial Lakṣmī”. She is not one particular blessing but the Goddess as she always is, inseparable from Viṣṇu, before and beyond any of the gifts the other seven bring.',
     'This guide tells who she is: her birth as the sage Bhṛgu’s daughter, her place in Śrīvaiṣṇava theology as the one who pleads for us, and her presence on Viṣṇu’s chest.'],
 pages=[('glance','AT A GLANCE','Ādi Lakṣmī on one page',[('Name','Ādi Lakṣmī, “the primordial Lakṣmī”; also Mahālakṣmī, Ramā'),('Gift','Not one gift but the source: grace and union with the Divine'),('Form','Four arms, holding a lotus and a white flag; the others in boon and fear-not gestures; often beside Viṣṇu'),('Colour','Usually pink-red sari on a lotus'),('Place in the eight','First'),('Seen at','Shrines of the Aṣṭalakṣmī temples; every Viṣṇu temple as his consort')],("A flag?","A white flag: a sign of peace and of her rule. The lotus is her own.")),
  ('birth','BHṚGU’S DAUGHTER','Her first birth',[('Viṣṇu Purāṇa','Lakṣmī was born to the sage Bhṛgu and his wife Khyāti, so she is called Bhārgavī'),('Later','Lost through Durvāsā’s curse, she rose again from the ocean of milk'),('Always','The Purāṇa says she is eternal: born again whenever Viṣṇu descends'),('Avatāras','Padmā with Vāmana, Dharaṇī with Paraśurāma, Sītā with Rāma, Rukmiṇī with Kṛṣṇa')]),
  ('inseparable','INSEPARABLE','Viṣṇu and Śrī',[('Viṣṇu Purāṇa','As he is meaning, she is speech; as he is the sun, she is its light'),('Śrīvatsa','The mark on Viṣṇu’s chest where she dwells'),('Śrīnivāsa','“Abode of Śrī”: Viṣṇu’s name at Tirumala'),('Lakṣmī-Nārāyaṇa','The pair worshipped together in countless temples')],("So she's never apart from him?","Never, the texts say. Even when they seem apart in a story, it's play.")),
  ('pancharatra','IN THE PĀÑCARĀTRA','Śrī as Viṣṇu’s power',[('Lakṣmī Tantra','A Pāñcarātra text in which Lakṣmī herself teaches Indra'),('Śakti','She is Viṣṇu’s śakti, his creative power; through her he acts'),('Six qualities','Knowledge, lordship, power, strength, valour and splendour belong to both'),('Ādi','In this view the “first Lakṣmī” is this cosmic power')]),
  ('purushakara','THE ONE WHO PLEADS','Puruṣakāra in Śrīvaiṣṇavism',[('Role','Śrī intercedes with Viṣṇu for the soul; she is the merciful mediator'),('Rāmānuja','His Śaraṇāgati Gadya begins with surrender to Śrī before Nārāyaṇa'),('Dvaya mantra','“I take refuge in the feet of Nārāyaṇa, with Śrī”'),('Debate','The Vaḍakalai and Teṅkalai schools differ on whether she can grant liberation herself or only mediate')],("Why go through her?","Like asking a mother to speak to a father. She is pure mercy.")),
  ('stotram','HER VERSE','In the Aṣṭalakṣmī Stotram',[('Theme','The first verse greets her as worshipped by sages, beautiful, Mādhava’s beloved, born of the moon’s family (the ocean)'),('She frees','It calls her the giver of liberation and sings of her sweet speech'),('Refrain','Each verse closes asking her to protect the singer always'),('Use','Begin the whole hymn and any Friday prayer with her')]),
  ('padmavati','PADMĀVATĪ OF TIRUMALA','Ādi Lakṣmī on earth',[('Story','When Lakṣmī left Vaikuṇṭha after Bhṛgu kicked Viṣṇu’s chest, Viṣṇu came to earth as Śrīnivāsa'),('Marriage','He married Padmāvatī, born on a lotus to King Ākāśa Rāja'),('Tiruchānūr','Her temple near Tirupati; pilgrims visit her before or after the Lord'),('Debt','By legend Śrīnivāsa borrowed from Kubera for the wedding; devotees help repay it')],("Bhṛgu kicked Viṣṇu?","To test which god was greatest. Viṣṇu forgave; Lakṣmī was offended, since his chest is her home.")),
  ('worship','HOW SHE IS WORSHIPPED','Ways to honour her',[('Śrī Sūkta','Recited at her abhiṣeka'),('Lakṣmī-Nārāyaṇa pūjā','With Viṣṇu, especially on Ekādaśī and Fridays'),('Lamp','A ghee lamp at dusk at the threshold, for her to enter'),('Clean home','Tradition: Ādi Lakṣmī enters a clean, peaceful home')]),
  ('meaning','WHAT SHE TEACHES','Grace before gifts',[('Source first','Seek the giver, not just the gifts'),('Partnership','Śrī and Viṣṇu: power and goodness together'),('Mercy','She pleads for the undeserving'),('Peace','The white flag: fortune grows in peace')],("What's the lesson?","The other seven are gifts. She is the one who gives.")),
 ],
 end=[('Who','The primordial Lakṣmī, Viṣṇu’s eternal consort'),('Birth','Bhṛgu’s daughter; again from the ocean'),('Theology','Viṣṇu’s śakti; the merciful mediator'),('On earth','Padmāvatī at Tirupati'),('Lesson','Seek the giver before the gifts')],endq=("One line?","Ādi Lakṣmī is Lakṣmī herself. The rest are her gifts."),
 src='Viṣṇu Purāṇa 1.8–1.9; Lakṣmī Tantra; Rāmānuja, Śaraṇāgati Gadya; Venkatachala Itihasa Mala and Tirumala tradition for Padmāvatī; Aṣṭalakṣmī temple iconography (Chennai).',
 unv='Iconography of each Lakṣmī varies by temple and picture; the Bhṛgu test story is from later Purāṇic tradition; the Vaḍakalai–Teṅkalai positions are summarised, not judged.',
 EX={'glance':['Of the eight, Ādi Lakṣmī is the hardest to picture as a “gift” because she is the giver. Many temples show her with Viṣṇu or with his symbols, to make the point that she is not a separate goddess of a single blessing but Śrī herself.','In some lists she is replaced or joined by Mahālakṣmī; in others she is called Ramā, “the delightful”. All these names point to the same idea: the Lakṣmī behind all Lakṣmīs.'],
  'birth':['The Viṣṇu Purāṇa explains Lakṣmī’s two births: first as daughter of Bhṛgu and Khyāti, then, after Durvāsā’s curse, from the churned ocean. The text reconciles them by saying she is eternal, like Viṣṇu, and simply appears in new ways.','Her name Bhārgavī, “Bhṛgu’s daughter”, is common in hymns. It also ties her to one of the great sage families, the Bhārgavas, who include Paraśurāma.'],
  'inseparable':['The images of speech and meaning, light and sun, are classic. They say that Viṣṇu and Lakṣmī are not two separate beings who happen to be married, but two aspects of one reality, as a word and its sense cannot be pulled apart.','Śrīvaiṣṇavas name their tradition after her, and say Viṣṇu is never worshipped without Śrī. The śrīvatsa mark on images of Viṣṇu is her seat on his chest.'],
  'pancharatra':['The Pāñcarātra Āgamas are the ritual and theological texts behind most Vaiṣṇava temple worship in South India. In the Lakṣmī Tantra she describes herself as the power by which Viṣṇu creates, sustains and dissolves the world.','This Ādi or primordial Lakṣmī is close to the Śākta idea of the Great Goddess, but always paired with Viṣṇu. The Kamalā of the Mahāvidyās, by contrast, sits alone.'],
  'purushakara':['Puruṣakāra, the mediator, is central to Śrīvaiṣṇava devotion. The soul, burdened with faults, approaches the Lord through his consort, whose compassion softens his justice. The Dvaya mantra, at the heart of the tradition, names Śrī with Nārāyaṇa.','The two later Śrīvaiṣṇava schools, Vaḍakalai and Teṅkalai, differ on whether Lakṣmī is fully equal to Viṣṇu and can grant liberation herself, or is the supreme mediator only. We present both without choosing.'],
  'padmavati':['The Tirumala legends, in the Veṅkaṭācala Māhātmya and later local texts, tell that the sage Bhṛgu, testing the gods, kicked Viṣṇu on the chest, where Lakṣmī lives. Viṣṇu apologised to the sage; Lakṣmī, hurt, left for earth. Viṣṇu followed as Śrīnivāsa.','Padmāvatī, born on a lotus, is taken as a form of Lakṣmī. Her temple at Tiruchānūr draws huge crowds, and a common saying is that a pilgrimage to Tirumala is not complete without visiting her.'],
  'worship':['Ādi Lakṣmī worship is simply Lakṣmī worship in its fullest form. The Śrī Sūkta is recited during her abhiṣeka in temples, and many homes keep a small Lakṣmī-Nārāyaṇa image for daily prayer.','Lighting a lamp at the doorway at dusk, an old custom across India, is said to welcome Lakṣmī into the house as the day ends.'],
  'meaning':['The lesson of the first Lakṣmī is about order: if the relationship with the source is right, the gifts follow. Chasing the gifts alone, the other seven, can lead to Alakṣmī.','Her pairing with Viṣṇu also teaches balance: prosperity joined to goodness. Wealth without dharma is not Lakṣmī.']})
D['dhanya']=dict(desc='Dhānya Lakṣmī, Lakṣmī of grain and harvest: her green form with paddy, sugarcane and bananas, the Śrī Sūkta’s earth-goddess, Annapūrṇā, harvest festivals like Saṅkrānti and Pongal, rice as wealth, and not wasting food.',
 tag='Lakṣmī of grain and harvest',fwq=("Grain is wealth?","The first wealth. No harvest, no anything else."),
 fw=['<b>Dhānya</b> means grain. Dhānya Lakṣmī is Lakṣmī in the fields: green-clad, holding sheaves of paddy, sugarcane and bananas. For most of history, wealth meant a full granary, and in a farming country it still does.',
     'This guide follows her from the Vedic hymn that calls Śrī “rich in cattle and ever-nourished”, through the harvest festivals, to the simple rule that rice is never wasted.'],
 pages=[('glance','AT A GLANCE','Dhānya Lakṣmī on one page',[('Name','Dhānya Lakṣmī, “Lakṣmī of grain”'),('Gift','Food, harvests and agricultural plenty'),('Form','Green sari; eight arms holding lotuses, a mace, paddy sheaves, sugarcane and bananas; others in boon and fear-not'),('Colour','Green, the colour of growing crops'),('Seen at','The Aṣṭalakṣmī temples; harvest altars at home')],("Why green?","The colour of a paddy field before harvest.")),
  ('roots','IN THE ŚRĪ SŪKTA','An earth goddess',[('Karīṣiṇī','The Śrī Sūkta calls her karīṣiṇī, “rich in dung”, that is, in cattle and fertile fields'),('Nityapuṣṭā','“Ever-nourished”'),('Gandhadvārā','“Whose door is fragrance”: the smell of earth after rain'),('Bhūdevī','Viṣṇu’s other consort, the Earth, is closely linked with this form')]),
  ('annapurna','ANNAPŪRṆĀ AND ANNAM','Food as the Goddess',[('Annapūrṇā','The Goddess “full of food” of Kāśī, who feeds even Śiva'),('Taittirīya','The Upaniṣad says: annaṃ brahma, food is Brahman; do not despise food'),('Dhānya and Anna','Grain in the store is Dhānya Lakṣmī; food on the plate is Annapūrṇā'),('Link','We have the Annapūrṇā Stotram verse by verse')],None,'<div class="key">See: <a href="/bhakti/devi/annapurna-stotram/">Annapūrṇā Stotram</a></div>'),
  ('stotram','HER VERSE','In the Aṣṭalakṣmī Stotram',[('Theme','Her verse calls her the destroyer of the dark age’s faults, a form of the Vedas, rich in mantras'),('Grain','It praises her as the giver of grain, the one who feeds the world'),('Refrain','It asks her to protect the singer always'),('Sung','At harvest-time pūjās and Saṅkrānti')]),
  ('harvests','HARVEST FESTIVALS','When she comes home',[('Makara Saṅkrānti','January: new rice cooked, cattle honoured; Pongal in Tamil Nadu, Bhogi and Kanuma in Andhra, Saṅkrānti in Karnataka with eḷḷu-bella'),('Navānna','“New grain” rites in Bengal, Odisha and Kerala (Puttari, Nira)'),('Onam','Kerala’s harvest festival'),('Rāśi pūjā','In some villages the grain heap on the threshing floor is worshipped before it is taken home')],("Is Pongal for Lakṣmī?","For the Sun, the cattle and the harvest. In all of it, people see Dhānya Lakṣmī.")),
  ('granary','THE GRANARY AS SHRINE','Customs at home',[('Paddy measure','In Karnataka and Tamil Nadu the grain measure (kolaga, paḍi) is treated with respect, sometimes worshipped'),('Never step','Do not step over grain or rice'),('Rice pot','Many homes never let the rice pot become completely empty'),('Lakṣmī’s feet','Rice-flour kōlam and rangoli at the door invite her in')]),
  ('waste','DO NOT WASTE FOOD','An old rule',[('Annaṃ na nindyāt','Taittirīya: do not despise food; annaṃ bahu kurvīta, make much food'),('Plates','Leaving food on the plate is called an insult to Lakṣmī'),('Sharing','Feeding guests and the hungry is the best use of grain'),('Today','A rule with new force when a third of food is wasted worldwide')]),
  ('farmers','THE FARMER’S GODDESS','Work and the harvest',[('Sowing','Seeds are blessed before sowing in many regions'),('Cattle','Bullocks, partners in the work, are honoured at Kanuma and Māṭṭu Pongal'),('Rain','Gaja Lakṣmī’s elephants are rain-clouds; Dhānya Lakṣmī is what the rain becomes'),('Respect','The farmer is called annadātā, giver of food')]),
  ('meaning','WHAT SHE TEACHES','The first wealth',[('Basic needs first','No one can study or fight hungry'),('Respect food','Waste is ingratitude'),('Share','Grain in store is meant to be eaten and given'),('Honour farmers','They bring her home')],("What's the lesson?","Respect the plate. That's Dhānya Lakṣmī.")),
 ],
 end=[('Who','Lakṣmī of grain and harvest'),('Roots','The Śrī Sūkta’s fertile, nourished Śrī; Bhūdevī'),('Festivals','Saṅkrānti, Pongal, Navānna, Onam'),('Customs','Respect grain; never empty the rice pot; feed others'),('Lesson','Food is the first wealth')],endq=("One line?","Every grain of rice is a little Lakṣmī."),
 src='Śrī Sūkta; Taittirīya Upaniṣad 3.7–3.10 (annaṃ na nindyāt…); Aṣṭalakṣmī temple iconography; regional harvest customs from state cultural sources; FAO estimates on food loss and waste.',
 unv='Iconography varies; the identification of Dhānya Lakṣmī with Bhūdevī is a common devotional link, not a fixed doctrine.',
 EX={'glance':['Dhānya Lakṣmī is the most concrete of the eight. She is wealth you can see and eat: grain, sugarcane, bananas. In an agricultural economy, a household’s security was measured in stored grain, and the word for wealth in many Indian languages still echoes this.','Her images often show her with sheaves of rice and sugarcane, as in harvest offerings at Saṅkrānti.'],
  'roots':['The Śrī Sūkta’s picture of Śrī is earthy: she is fragrant, nourished, rich in cattle and dung, words that seem strange today but meant fertility and plenty to Vedic farmers. Dung was fuel and fertiliser, and a herd meant wealth.','Bhūdevī, the Earth, is Viṣṇu’s second consort in South Indian temples, standing on his left while Śrīdevī stands on his right. Dhānya Lakṣmī carries something of both.'],
  'annapurna':['The Taittirīya Upaniṣad’s teaching on food is remarkable: the student Bhṛgu is taught that food is Brahman, and given vows: never despise food, never reject it, make plenty of it. These lines are still recited in many hostels and homes before meals.','Annapūrṇā at Kāśī holds a ladle and a bowl; in her famous story she gives alms to Śiva himself, who comes as a beggar. Food, in this view, is sacred because it is life.'],
  'stotram':['Her verse in the Stotram mixes the cosmic and the practical: she is called a form of the Vedas, yet her gift is grain. The juxtaposition is typical of Indian thought, where the highest and the most ordinary meet.','As with the other forms, we describe her verse rather than print it, since the Stotram is a recent composition.'],
  'harvests':['Makara Saṅkrānti, when the sun enters Capricorn in mid-January, is India’s great harvest festival under many names. In Karnataka, eḷḷu-bella, a mix of sesame, jaggery, coconut and peanuts, is shared with the words “eat sesame and jaggery, speak sweetly”.','Kerala’s Nira and Puttari ceremonies bring the first sheaves of paddy into homes and temples, where they are hung at the door through the year as a sign of plenty.'],
  'granary':['The customs around grain are small but telling: grain measures were kept clean and sometimes decorated; the rice store was never allowed to run out completely; and rangoli made of rice flour fed ants and birds at the threshold, an act of sharing.','In many homes the first handful of cooked rice is set aside for crows or cows before the family eats.'],
  'waste':['The rule against wasting food is one of the most universal in Indian homes, often taught with the phrase that Lakṣmī will leave the house. It has a practical root in centuries of scarcity and famine.','Today it has a new resonance. Global estimates suggest that a large share of the food produced in the world is lost or wasted, while many still go hungry.'],
  'farmers':['Dhānya Lakṣmī is the farmer’s goddess. Her worship ties religion to the rhythm of sowing, rain and harvest, and honours the bullocks and cows who share the work.','Calling the farmer annadātā, “giver of food”, puts the one who grows grain at the centre of the economy, a reminder easily forgotten in cities.'],
  'meaning':['Dhānya Lakṣmī asks for gratitude at the most basic level: for the meal in front of us and the people who grew it. Everything else, learning, courage, success, rests on it.','She also teaches sharing: grain hoarded rots, grain shared feeds a village.']})
for i,k in enumerate(['adi','dhanya']): FORM(i,D[k])
